$user=require_family_access();$pdo=db();$tid=(int)$user['tenant_id'];$csrf=csrf_token();$flash=pull_flash();
$q=$pdo->prepare('SELECT name,max_members FROM tenants WHERE id=? AND active=1');$q->execute([$tid]);$family=$q->fetch();
$q=$pdo->prepare("SELECT role FROM tenant_users WHERE tenant_id=? AND user_id=?");$q->execute([$tid,(int)$user['id']]);$isAdmin=$q->fetchColumn()==='family_admin';
$q=$pdo->prepare("SELECT u.id,u.name,u.email,tu.role,tu.created_at FROM tenant_users tu JOIN users u ON u.id=tu.user_id WHERE tu.tenant_id=? ORDER BY (tu.role='family_admin') DESC,u.name");
$q->execute([$tid]);$members=$q->fetchAll();$count=count($members);$max=(int)($family['max_members']??0);
