<section class="members-hero"><div class="members-hero-icon"><i class="bi bi-people-fill"></i></div><div><h2><?= e($family['name']??'Sua família') ?></h2><p>Visualize quem tem acesso e mantenha sua família organizada.</p></div><div class="members-counter"><strong><?= $count ?> <span>/ <?= $max ?></span></strong><small>Membros cadastrados</small></div></section>
<div class="members-heading"><div><h2>Integrantes da família</h2><p><?= $count ?> <?= $count===1?'pessoa cadastrada':'pessoas cadastradas' ?> · <?= max(0,$max-$count) ?> <?= max(0,$max-$count)===1?'vaga disponível':'vagas disponíveis' ?></p></div>
<?php if($isAdmin && $count<$max): ?><button class="btn btn-success" type="button" id="add-member-toggle" aria-controls="add-member-panel" aria-expanded="false"><i class="bi bi-person-plus"></i> Adicionar membro</button><?php endif; ?></div>
<?php if($isAdmin && $count<$max): ?><section class="members-add" id="add-member-panel" hidden><h3>Novo membro</h3><p>Crie um acesso individual. A senha temporária aparecerá após o cadastro.</p><form method="post" action="/membros/acao"><input type="hidden" name="csrf_token" value="<?= e($csrf) ?>"><input type="hidden" name="action" value="add"><div class="members-add-grid"><label>Nome completo<input name="name" type="text" maxlength="80" minlength="2" class="form-control" autocomplete="off" required placeholder="Nome do membro"></label><label>E-mail<input name="email" type="email" maxlength="160" class="form-control" autocomplete="off" required placeholder="exemplo@email.com"></label></div><button class="btn btn-success" type="submit"><i class="bi bi-person-check"></i> Criar acesso</button></form></section>
<?php endif; ?>
<div class="members-grid">
<?php foreach($members as $member): ?><article class="member-card"><div class="member-card-head"><span class="member-avatar"><?= e(mb_strtoupper(mb_substr((string)$member['name'],0,1))) ?></span><div class="member-identity"><h3><?= e($member['name']) ?><?php if((int)$member['id']===(int)$user['id']): ?><span class="member-you">Você</span><?php endif; ?></h3><p><?= e($member['email']) ?></p></div></div><div class="member-card-meta"><span class="member-role <?= $member['role']==='family_admin'?'admin':'' ?>"><i class="bi <?= $member['role']==='family_admin'?'bi-shield-check':'bi-person-check' ?>"></i> <?= $member['role']==='family_admin'?'Administrador familiar':'Membro' ?></span><small>Desde <?= e((new DateTimeImmutable($member['created_at']))->format('d/m/Y')) ?></small></div>
<?php if($isAdmin && (int)$member['id']!==(int)$user['id'] && $member['role']!=='family_admin'): ?><div class="member-card-actions"><form method="post" action="/membros/acao" class="member-reset-form" data-member="<?= e($member['name']) ?>"><input type="hidden" name="csrf_token" value="<?= e($csrf) ?>"><input type="hidden" name="action" value="reset_password"><input type="hidden" name="user_id" value="<?= (int)$member['id'] ?>"><button class="btn btn-outline-success" type="submit"><i class="bi bi-key"></i> Redefinir senha</button></form>
<form method="post" action="/membros/acao" class="member-remove-form" data-member="<?= e($member['name']) ?>"><input type="hidden" name="csrf_token" value="<?= e($csrf) ?>"><input type="hidden" name="action" value="remove"><input type="hidden" name="user_id" value="<?= (int)$member['id'] ?>"><input type="hidden" name="confirm_remove" value="REMOVE"><button class="btn btn-outline-danger" type="submit"><i class="bi bi-person-x"></i> Remover</button></form></div><?php endif; ?></article><?php endforeach; ?></div>
